python3 - <<'PY'
import json, pathlib, urllib.request, urllib.error
p=pathlib.Path('/Users/radoniusz/Library/Developer/CoreSimulator/Devices/BD1DCA41-5F4A-4EAF-A7F9-A641D2384C2B/data/Containers/Data/Application/84A2FAE0-845A-468A-B5C1-777CDE5D51B2/Library/Application Support/xyz.blueskyweb.app/RCTAsyncLocalStorage_V1/6b4d31064d04d1c547f0f2deeac0ba07')
d=json.loads(p.read_text()); a=d['session']['currentAccount']; base=a['service'].rstrip('/')
def get(path):
 req=urllib.request.Request(base+'/xrpc/'+path, headers={'Authorization':'Bearer '+a['accessJwt']})
 with urllib.request.urlopen(req, timeout=8) as r: return json.load(r)
for path in ['com.atproto.server.getSession','app.bsky.feed.getTimeline?limit=5']:
 try:
  data=get(path)
  if 'feed' in data:
   for i,item in enumerate(data['feed']):
    post=item['post']; print(i,post.get('author',{}).get('handle'),post.get('record',{}).get('text'),post.get('uri'),post.get('cid'))
  else: print(path,'ok',data.get('did'),data.get('handle'))
 except Exception as e: print(path, type(e).__name__, e)
PY

